import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    strings = input_data[1:n+1]

    strings.sort(key=len)

    possible = True
    for i in range(n - 1):
        if strings[i] not in strings[i+1]:
            possible = False
            break

    if possible:
        print("YES")
        for s in strings:
            print(s)
    else:
        print("NO")

if __name__ == "__main__":
    main()
